# Tide schedule

```ghost
// Explicit source revision: issue531-natural-policy-input-v1
control TideSchedule {
  input stop, unsafe_level: Bool;
  provider harbor_tides: TidePredictions;
  schedule high: Tide {
    source = harbor_tides;
    timezone = "Asia/Seoul";
    at = tide`high - 30min`;
    basis = run(10min, within(5min));
    when = true;
    cancel_when = (stop |> recover(true)) || (unsafe_level |> recover(true));
    clock = trusted_only;
    gap = skip_after(60s);
    recovery = baseline;
    fallback = skip;
  }
  output active: Bool;
  active <- high.active;
}
